contracts/MultiSigWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title MultiSigWallet
 * @dev Multi-signature wallet contract supporting multi-signature verification and transaction execution
 * @notice Provides secure fund management and transaction confirmation mechanism
 */
contract MultiSigWallet {
    // ============ Event Definitions ============

    /// @notice Signer added event
    event SignerAdded(address indexed signer);

    /// @notice Signer removed event
    event SignerRemoved(address indexed signer);

    /// @notice Signers replaced event
    event SignersReplaced(address[] newSigners);

    /// @notice Required confirmations changed event
    event RequiredConfirmationsChanged(uint256 newRequired);

    /// @notice Transaction submitted event
    event TransactionSubmitted(uint256 indexed txId, address indexed proposer);

    /// @notice Transaction confirmed event
    event TransactionConfirmed(uint256 indexed txId, address indexed signer);

    /// @notice Transaction executed event
    event TransactionExecuted(uint256 indexed txId);

    // ============ Struct Definitions ============

    /// @notice Transaction struct
    struct Transaction {
        address to; // Target address
        uint256 value; // Transfer amount
        bytes data; // Call data
        bool executed; // Whether executed
    }

    // ============ State Variables ============

    /// @notice Signer address array
    address[] public signers;

    /// @notice Signer mapping
    mapping(address => bool) public isSigner;

    /// @notice Transaction confirmation mapping
    mapping(uint256 => mapping(address => bool)) public hasConfirmed;

    /// @notice Required confirmation count
    uint256 public requiredConfirmations;

    /// @notice Transaction counter
    uint256 public transactionCount;

    /// @notice Transaction mapping
    mapping(uint256 => Transaction) public transactions;

    // ============ Modifiers ============

    /// @notice Only signers can call
    modifier onlySigner() {
        require(isSigner[msg.sender], "Not a signer");
        _;
    }

    /// @notice Transaction must exist
    modifier txExists(uint256 _txId) {
        require(_txId < transactionCount, "Transaction does not exist");
        _;
    }

    /// @notice Transaction not confirmed
    modifier notConfirmed(uint256 _txId) {
        require(
            !hasConfirmed[_txId][msg.sender],
            "Transaction already confirmed"
        );
        _;
    }

    /// @notice Transaction not executed
    modifier notExecuted(uint256 _txId) {
        require(!transactions[_txId].executed, "Transaction already executed");
        _;
    }

    // ============ Constructor ============

    /// @notice Initialize multi-signature wallet
    /// @param _signers Signer address array
    /// @param _required Required confirmation count
    constructor(address[] memory _signers, uint256 _required) {
        require(
            _signers.length >= _required,
            "Required must not exceed signer count"
        );
        require(_required > 1, "Required must be greater than 1");
        require(_signers.length > 0, "Must have at least one signer");

        for (uint i = 0; i < _signers.length; i++) {
            address signer = _signers[i];
            require(signer != address(0), "Invalid signer address");
            require(!isSigner[signer], "Duplicate signer");
            signers.push(signer);
            isSigner[signer] = true;
            emit SignerAdded(signer);
        }

        requiredConfirmations = _required;
        emit RequiredConfirmationsChanged(_required);
    }

    // ============ Transaction Management Functions ============

    /// @notice Submit transaction
    /// @param _to Target address
    /// @param _value Transfer amount
    /// @param _data Call data
    /// @return Transaction ID
    function submitTransaction(
        address _to,
        uint256 _value,
        bytes memory _data
    ) public onlySigner returns (uint256) {
        require(_to != address(0), "Invalid recipient address");
        uint256 txId = transactionCount;
        transactions[txId] = Transaction({
            to: _to,
            value: _value,
            data: _data,
            executed: false
        });
        transactionCount++;
        emit TransactionSubmitted(txId, msg.sender);

        // Automatically confirm proposer's transaction
        hasConfirmed[txId][msg.sender] = true;
        emit TransactionConfirmed(txId, msg.sender);

        return txId;
    }

    /// @notice Confirm transaction
    /// @param _txId Transaction ID
    function confirmTransaction(
        uint256 _txId
    ) public onlySigner txExists(_txId) notConfirmed(_txId) notExecuted(_txId) {
        hasConfirmed[_txId][msg.sender] = true;
        emit TransactionConfirmed(_txId, msg.sender);

        // Count confirmations from current signers
        uint256 confirmationCount = 0;
        for (uint i = 0; i < signers.length; i++) {
            if (hasConfirmed[_txId][signers[i]]) {
                confirmationCount++;
            }
        }

        if (confirmationCount >= requiredConfirmations) {
            executeTransaction(_txId);
        }
    }

    /// @notice Execute transaction
    /// @param _txId Transaction ID
    function executeTransaction(uint256 _txId) internal notExecuted(_txId) {
        Transaction storage transaction = transactions[_txId];

        // Count confirmations from current signers
        uint256 confirmationCount = 0;
        for (uint i = 0; i < signers.length; i++) {
            if (hasConfirmed[_txId][signers[i]]) {
                confirmationCount++;
            }
        }

        require(
            confirmationCount >= requiredConfirmations,
            "Not enough confirmations"
        );

        // Mark as executed before external call to prevent reentrancy
        transaction.executed = true;

        // Execute transaction
        (bool success, bytes memory returnData) = transaction.to.call{
            value: transaction.value
        }(transaction.data);

        // If the call failed, revert with the error message
        if (!success) {
            // Try to decode the error message
            string memory errorMessage;
            try this.decodeError(returnData) returns (string memory message) {
                errorMessage = message;
            } catch {
                errorMessage = "Transaction execution failed with no error message";
            }
            revert(errorMessage);
        }

        emit TransactionExecuted(_txId);
    }

    // ============ Signer Management Functions ============

    /// @notice Replace signers
    /// @param _newSigners New signer array
    /// @param _newRequired New confirmation requirement
    function replaceSigners(
        address[] memory _newSigners,
        uint256 _newRequired
    ) external {
        require(msg.sender == address(this), "Only through multisig");
        require(
            _newSigners.length >= _newRequired,
            "Required must not exceed signer count"
        );
        require(_newRequired > 1, "Required must be greater than 1");
        require(_newSigners.length > 0, "Must have at least one signer");

        // Clear old signers
        for (uint i = 0; i < signers.length; i++) {
            isSigner[signers[i]] = false;
        }

        // Add new signers
        delete signers;
        for (uint i = 0; i < _newSigners.length; i++) {
            address signer = _newSigners[i];
            require(signer != address(0), "Invalid signer address");
            require(!isSigner[signer], "Duplicate signer");
            signers.push(signer);
            isSigner[signer] = true;
        }

        requiredConfirmations = _newRequired;
        emit SignersReplaced(_newSigners);
        emit RequiredConfirmationsChanged(_newRequired);
    }

    // ============ Query Functions ============

    /// @notice Get signer list
    /// @return Signer address array
    function getSigners() external view returns (address[] memory) {
        return signers;
    }

    /// @notice Get required confirmation count
    /// @return Confirmation count
    function getRequiredConfirmations() external view returns (uint256) {
        return requiredConfirmations;
    }

    // ============ Receive Functions ============

    /// @notice Receive native token
    receive() external payable {}

    // ============ Helper Functions ============

    /// @notice Decode error message
    /// @param _returnData Return data
    /// @return Error message
    function decodeError(
        bytes memory _returnData
    ) external pure returns (string memory) {
        if (_returnData.length < 68) return "Unknown error";
        bytes memory errorMessage = new bytes(_returnData.length - 4);
        for (uint i = 4; i < _returnData.length; i++) {
            errorMessage[i - 4] = _returnData[i];
        }
        return string(errorMessage);
    }
}

