    }

    function pubkeyToUncompresed(
        uint256[2] memory compressed,
        uint256[2] memory y
    ) internal pure returns (uint256[4] memory uncompressed) {
        uint256 desicion = compressed[0] & SIGN_MASK;
        require(
            desicion == ODD_NUM || y[0] & 1 != 1,
            "BLS: bad y coordinate for uncompressing key"
        );
        uncompressed[0] = compressed[0] & FIELD_MASK;
        uncompressed[1] = compressed[1];
        uncompressed[2] = y[0];
        uncompressed[3] = y[1];
    }

    function signatureToUncompresed(
        uint256 compressed,
        uint256 y
    ) internal pure returns (uint256[2] memory uncompressed) {
        uint256 desicion = compressed & SIGN_MASK;
        require(
            desicion == ODD_NUM || y & 1 != 1,
            "BLS: bad y coordinate for uncompressing key"
        );
        return [compressed & FIELD_MASK, y];
    }

    function isValidCompressedPublicKey(
        uint256[2] memory publicKey
    ) internal view returns (bool) {
        uint256 x0 = publicKey[0] & FIELD_MASK;
        uint256 x1 = publicKey[1];
        if ((x0 >= N) || (x1 >= N)) {
            return false;
        } else if ((x0 == 0) && (x1 == 0)) {
            return false;
        } else {
            return isOnCurveG2([x0, x1]);
        }
    }

    function isValidCompressedSignature(
        uint256 signature
    ) internal view returns (bool) {
        uint256 x = signature & FIELD_MASK;
        if (x >= N) {
            return false;
        } else if (x == 0) {
            return false;
        }
        return isOnCurveG1(x);
    }

    function isOnCurveG1(
        uint256[2] memory point
    ) internal pure returns (bool _isOnCurve) {
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            let t0 := mload(point)
            let t1 := mload(add(point, 32))
            let t2 := mulmod(t0, t0, N)
            t2 := mulmod(t2, t0, N)
            t2 := addmod(t2, 3, N)
            t1 := mulmod(t1, t1, N)
            _isOnCurve := eq(t1, t2)
        }
    }

    function isOnCurveG1(uint256 x) internal view returns (bool _isOnCurve) {
        bool callSuccess;
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            let t0 := x
            let t1 := mulmod(t0, t0, N)
            t1 := mulmod(t1, t0, N)
            t1 := addmod(t1, 3, N)

            let freemem := mload(0x40)
            mstore(freemem, 0x20)
            mstore(add(freemem, 0x20), 0x20)
            mstore(add(freemem, 0x40), 0x20)
            mstore(add(freemem, 0x60), t1)
            // (N - 1) / 2 = 0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            mstore(
                add(freemem, 0x80),
                0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            )
            // N = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            mstore(
                add(freemem, 0xA0),
                0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            )
            callSuccess := staticcall(
                sub(gas(), 2000),
                5,
                freemem,
                0xC0,
                freemem,
                0x20
            )
            _isOnCurve := eq(1, mload(freemem))
        }
    }

    function isOnCurveG2(
        uint256[4] memory point
    ) internal pure returns (bool _isOnCurve) {
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            // x0, x1
            let t0 := mload(point)
            let t1 := mload(add(point, 32))
            // x0 ^ 2
            let t2 := mulmod(t0, t0, N)
            // x1 ^ 2
            let t3 := mulmod(t1, t1, N)
            // 3 * x0 ^ 2
            let t4 := add(add(t2, t2), t2)
            // 3 * x1 ^ 2
            let t5 := addmod(add(t3, t3), t3, N)
            // x0 * (x0 ^ 2 - 3 * x1 ^ 2)
            t2 := mulmod(add(t2, sub(N, t5)), t0, N)
            // x1 * (3 * x0 ^ 2 - x1 ^ 2)
            t3 := mulmod(add(t4, sub(N, t3)), t1, N)

            // x ^ 3 + b
            t0 := addmod(
                t2,
                0x2b149d40ceb8aaae81be18991be06ac3b5b4c5e559dbefa33267e6dc24a138e5,
                N
            )
            t1 := addmod(
                t3,
                0x009713b03af0fed4cd2cafadeed8fdf4a74fa084e52d1852e4a2bd0685c315d2,
                N
            )

            // y0, y1
            t2 := mload(add(point, 64))
            t3 := mload(add(point, 96))
            // y ^ 2
            t4 := mulmod(addmod(t2, t3, N), addmod(t2, sub(N, t3), N), N)
            t3 := mulmod(shl(1, t2), t3, N)

            // y ^ 2 == x ^ 3 + b
            _isOnCurve := and(eq(t0, t4), eq(t1, t3))
        }
    }

    function isOnCurveG2(
        uint256[2] memory x
    ) internal view returns (bool _isOnCurve) {
        bool callSuccess;
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            // x0, x1
            let t0 := mload(add(x, 0))
            let t1 := mload(add(x, 32))
            // x0 ^ 2
            let t2 := mulmod(t0, t0, N)
            // x1 ^ 2
            let t3 := mulmod(t1, t1, N)
            // 3 * x0 ^ 2
            let t4 := add(add(t2, t2), t2)
            // 3 * x1 ^ 2
            let t5 := addmod(add(t3, t3), t3, N)
            // x0 * (x0 ^ 2 - 3 * x1 ^ 2)
            t2 := mulmod(add(t2, sub(N, t5)), t0, N)
            // x1 * (3 * x0 ^ 2 - x1 ^ 2)
            t3 := mulmod(add(t4, sub(N, t3)), t1, N)
            // x ^ 3 + b
            t0 := add(
                t2,
                0x2b149d40ceb8aaae81be18991be06ac3b5b4c5e559dbefa33267e6dc24a138e5
            )
            t1 := add(
                t3,
                0x009713b03af0fed4cd2cafadeed8fdf4a74fa084e52d1852e4a2bd0685c315d2
            )

            // is non residue ?
            t0 := addmod(mulmod(t0, t0, N), mulmod(t1, t1, N), N)
            let freemem := mload(0x40)
            mstore(freemem, 0x20)
            mstore(add(freemem, 0x20), 0x20)
            mstore(add(freemem, 0x40), 0x20)
            mstore(add(freemem, 0x60), t0)
            // (N - 1) / 2 = 0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            mstore(
                add(freemem, 0x80),
                0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            )
            // N = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            mstore(
                add(freemem, 0xA0),
                0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            )
            callSuccess := staticcall(
                sub(gas(), 2000),
                5,
                freemem,
                0xC0,
                freemem,
                0x20
            )
            _isOnCurve := eq(1, mload(freemem))
        }
    }

    function isNonResidueFP(
        uint256 e
    ) internal view returns (bool isNonResidue) {
        bool callSuccess;
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            let freemem := mload(0x40)
            mstore(freemem, 0x20)
            mstore(add(freemem, 0x20), 0x20)
            mstore(add(freemem, 0x40), 0x20)
            mstore(add(freemem, 0x60), e)
            // (N - 1) / 2 = 0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            mstore(
                add(freemem, 0x80),
                0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            )
            // N = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            mstore(
                add(freemem, 0xA0),
                0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            )
            callSuccess := staticcall(
                sub(gas(), 2000),
                5,
                freemem,
                0xC0,
                freemem,
                0x20
            )
            isNonResidue := eq(1, mload(freemem))
        }
        require(callSuccess, "BLS: isNonResidueFP modexp call failed");
        return !isNonResidue;
    }

    function isNonResidueFP2(
        uint256[2] memory e
    ) internal view returns (bool isNonResidue) {
        uint256 a = addmod(mulmod(e[0], e[0], N), mulmod(e[1], e[1], N), N);
        bool callSuccess;
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            let freemem := mload(0x40)
            mstore(freemem, 0x20)
            mstore(add(freemem, 0x20), 0x20)
            mstore(add(freemem, 0x40), 0x20)
            mstore(add(freemem, 0x60), a)
            // (N - 1) / 2 = 0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            mstore(
                add(freemem, 0x80),
                0x183227397098d014dc2822db40c0ac2ecbc0b548b438e5469e10460b6c3e7ea3
            )
            // N = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            mstore(
                add(freemem, 0xA0),
                0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            )
            callSuccess := staticcall(
                sub(gas(), 2000),
                5,
                freemem,
                0xC0,
                freemem,
                0x20
            )
            isNonResidue := eq(1, mload(freemem))
        }
        require(callSuccess, "BLS: isNonResidueFP2 modexp call failed");
        return !isNonResidue;
    }

    function sqrt(uint256 xx) internal view returns (uint256 x, bool hasRoot) {
        bool callSuccess;
        // solium-disable-next-line security/no-inline-assembly
        assembly {
            let freemem := mload(0x40)
            mstore(freemem, 0x20)
            mstore(add(freemem, 0x20), 0x20)
            mstore(add(freemem, 0x40), 0x20)
            mstore(add(freemem, 0x60), xx)
            // (N + 1) / 4 = 0xc19139cb84c680a6e14116da060561765e05aa45a1c72a34f082305b61f3f52
            mstore(
                add(freemem, 0x80),
                0xc19139cb84c680a6e14116da060561765e05aa45a1c72a34f082305b61f3f52
            )
            // N = 0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            mstore(
                add(freemem, 0xA0),
                0x30644e72e131a029b85045b68181585d97816a916871ca8d3c208c16d87cfd47
            )
            callSuccess := staticcall(
                sub(gas(), 2000),
                5,
                freemem,
                0xC0,
                freemem,
                0x20
            )
            x := mload(freemem)
            hasRoot := eq(xx, mulmod(x, x, N))
        }
        require(callSuccess, "BLS: sqrt modexp call failed");
    }
}

contracts/SideBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title SideBridge
 * @dev Side chain bridge contract responsible for handling token transfers from side chain to main chain
 * @notice Supports cross-chain transfers of ERC20 tokens and native tokens, using BLS signature verification
 */
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./MultiSigWallet.sol";
import "./interfaces/ICysicToken.sol";
import "./BLS.sol";

contract SideBridge is Initializable, UUPSUpgradeable, PausableUpgradeable {
    using SafeERC20 for IERC20;

    // ============ Event Definitions ============

    /// @notice Token mapping event
    event TokenMapped(address indexed sourceToken, address indexed targetToken);

    /// @notice Deposit initiation event
    event InitDeposit(
        address indexed token,
        address indexed from,
        uint256 amount,
        address indexed recipient,
        uint256 targetChainId,
        uint256 nonce
    );

    /// @notice Withdrawal completion event
    event FinishWithdraw(
        address indexed token,
        address indexed recipient,
        uint256 amount,
        bytes32 depositId
    );

    /// @notice Native token rescue event
    event NativeTokenRescued(uint256 amount, address recipient);

    /// @notice ERC20 token rescue event
    event ERC20TokenRescued(address token, uint256 amount, address recipient);

    /// @notice BLS signature debug event
    event BLSSignatureDebug(
        bytes32 messageHash,
        uint256 sigX,
        uint256 sigY,
        uint256 sigLength
    );

    // ============ State Variables ============

    /// @notice Multi-signature wallet contract address
    MultiSigWallet public multiSigWallet;

    /// @notice Cysic chain ID
    uint256 public cysicChainId;

    /// @notice Token mapping: sourceToken => targetToken (pass 0 address to cancel mapping)
    mapping(address => address) public tokenMapping;

    /// @notice Token operation permission: sourceToken => canOperation
    mapping(address => bool) public tokenCanOperation;

    /// @notice Native token special address
    address public constant NATIVE_TOKEN =
        0x0000000000000000000000000000000000000001;

    /// @notice Wrapped native token address on this chain
    address public wrappedNative;

    /// @notice Withdrawal nonce for each chain
    mapping(uint256 => uint256) public withdrawChainNonce;

    /// @notice Used nonce records
    mapping(bytes32 => bool) public usedNonces;

    /// @notice Deposit nonce for each chain
    mapping(uint256 => uint256) public depositChainNonce;

    /// @notice Rescue operation time lock
    uint256 public constant RESCUE_TIMELOCK = 7 days;

    /// @notice Last update timestamp
    uint256 public lastUpdateTimestamp;

    /// @notice Rescue request initiation time (independent of business operation time)
    uint256 public rescueRequestedAt;

    /// @notice BLS public key array
    uint256[4][] public blsPublicKeys;

    /// @notice BLS signature threshold
    uint256 public blsThreshold;

    /// @notice BLS public key existence mapping (using hash markers for O(1) duplicate detection)
    mapping(bytes32 => bool) private blsPublicKeyExists;

    /// @notice Batch withdrawal request structure to reduce batch function parameter count
    struct WithdrawalRequest {
        address token;
        address recipient;
        uint256 amount;
        bytes32 depositId;
        uint256 sourceChainId;
        uint256 nonce;
        uint256[2] signatures;
        uint256[] signerIndices;
    }

    // ============ Modifiers ============

    /// @notice Only multi-signature wallet can call
    modifier onlyMultiSig() {
        require(
            msg.sender == address(multiSigWallet),
            "Only multisig can call"
        );
        _;
    }

    /// @notice Update last operation time
    modifier updateLastOperationTime() {
        _;
        lastUpdateTimestamp = block.timestamp;
    }

    // ============ Constructor ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // ============ Initialization Functions ============

    /// @notice Initialize contract
    /// @param _multiSig Multi-signature wallet address
    /// @param _cysicChainId Cysic chain ID
    /// @param _wrappedNative Wrapped native token address
    function initialize(
        address payable _multiSig,
        uint256 _cysicChainId,
        address _wrappedNative
    ) public initializer {
        require(_multiSig != address(0), "Invalid multisig address");
        require(_cysicChainId > 0, "Invalid chain ID");
        require(_wrappedNative != address(0), "Invalid wrapped native address");

        multiSigWallet = MultiSigWallet(_multiSig);
        cysicChainId = _cysicChainId;
        wrappedNative = _wrappedNative;

        __UUPSUpgradeable_init();
        __Pausable_init();
    }

    // ============ Token Mapping Functions ============

    /// @notice Map token
    /// @param _sourceToken Source token address
    /// @param _targetToken Target token address
    /// @param name Token name
    /// @param symbol Token symbol
    /// @param canOperation Whether mint/burn operations are supported
    function mapToken(
        address _sourceToken,
        address _targetToken,
        string memory name,
        string memory symbol,
        bool canOperation
    ) external onlyMultiSig updateLastOperationTime {
        require(
            _sourceToken != address(0),
            "Source token cannot be zero address"
        );

        // Passing 0 address means cancel mapping
        if (_targetToken == address(0)) {
            require(
                tokenMapping[_sourceToken] != address(0),
                "Token not mapped"
            );
            tokenMapping[_sourceToken] = address(0);
            tokenCanOperation[_sourceToken] = false;
            emit TokenMapped(_sourceToken, address(0));
            return;
        }

        // Add or update mapping
        require(
            bytes(name).length > 0 && bytes(name).length <= 32,
            "Invalid name length"
        );
        require(
            bytes(symbol).length > 0 && bytes(symbol).length <= 8,
            "Invalid symbol length"
        );

        tokenMapping[_sourceToken] = _targetToken;
        tokenCanOperation[_sourceToken] = canOperation;
        emit TokenMapped(_sourceToken, _targetToken);
    }

    // ============ Cross-Chain Deposit Functions ============

    /// @notice Deposit from side chain to main chain
    /// @param _token Token address (NATIVE_TOKEN represents native token)
    /// @param _amount Deposit amount
    /// @param _recipient Recipient address
    function deposit(
        address _token,
        uint256 _amount,
        address _recipient
    ) external payable whenNotPaused updateLastOperationTime {
        require(_recipient != address(0), "Invalid recipient address");
        require(tokenMapping[_token] != address(0), "Token not supported");

        uint256 actualAmount;

        // Check if it is native token
        if (_token == NATIVE_TOKEN) {
            // Native token handling
            require(msg.value > 0, "Amount must be greater than 0");
            actualAmount = msg.value;
        } else {
            // ERC20 token handling
            require(_amount > 0, "Amount must be greater than 0");
            bool canOperation = tokenCanOperation[_token];
            if (canOperation) {
                // If burn operation is supported, burn the tokens
                IERC20(_token).safeTransferFrom(
                    msg.sender,
                    address(this),
                    _amount
                );
                ICysicToken(_token).burnFromAddress(address(this), _amount);
            } else {
                // If burn operation is not supported, lock tokens in the contract
                IERC20(_token).safeTransferFrom(
                    msg.sender,
                    address(this),
                    _amount
                );
            }
            actualAmount = _amount;
        }

        // Generate nonce for this deposit
        uint256 nonce = depositChainNonce[cysicChainId]++;

        // Emit event for off-chain validators to process
        emit InitDeposit(
            _token,
            msg.sender,
            actualAmount,
            _recipient,
            cysicChainId,
            nonce
        );
    }

    // ============ Cross-Chain Withdrawal Functions ============

    /// @notice Withdraw from main chain to side chain
    /// @param _token Token address
    /// @param _recipient Recipient address
    /// @param _amount Withdrawal amount
    /// @param _depositId Deposit ID
    /// @param _sourceChainId Source chain ID
    /// @param _nonce Transaction nonce
    /// @param _signatures Validator signatures
    function withdraw(
        address _token,
        address _recipient,
        uint256 _amount,
        bytes32 _depositId,
        uint256 _sourceChainId,
        uint256 _nonce,
        uint256[2] memory _signatures,
        uint256[] memory _signerIndices
    ) external whenNotPaused updateLastOperationTime {
        _withdrawSingle(
            _token,
            _recipient,
            _amount,
            _depositId,
            _sourceChainId,
            _nonce,
            _signatures,
            _signerIndices
        );
    }

    /// @notice Internal single withdrawal processing (no modifier)
    function _withdrawSingle(
        address _token,
        address _recipient,
        uint256 _amount,
        bytes32 _depositId,
        uint256 _sourceChainId,
        uint256 _nonce,
        uint256[2] memory _signatures,
        uint256[] memory _signerIndices
    ) internal {
        require(
            tokenMapping[_token] != address(0),
            "Token not supported: mapping missing for token on side chain"
        );
        require(
            _recipient != address(0),
            "Invalid recipient address: zero address"
        );
        require(_amount > 0, "Invalid amount: must be greater than 0");

        bytes32 messageHash = keccak256(
            abi.encodePacked(
                _token,
                _recipient,
                _amount,
                _sourceChainId,
                _nonce,
                address(this)
            )
        );
        require(!usedNonces[messageHash], "Nonce already used");
        require(
            verifySignatures(messageHash, _signatures, _signerIndices),
            "Invalid signatures"
        );
        usedNonces[messageHash] = true;

        if (_token == NATIVE_TOKEN) {
            (bool success, ) = _recipient.call{value: _amount}("");
            require(success, "Native token transfer failed: call reverted");
        } else {
            bool canOperation = tokenCanOperation[_token];
            address sideToken = _token;
            if (canOperation) {
                ICysicToken(sideToken).mint(_recipient, _amount);
            } else {
                uint256 bridgeBalance = IERC20(sideToken).balanceOf(
                    address(this)
                );
                require(
                    bridgeBalance >= _amount,
                    "ERC20 transfer failed: insufficient bridge token balance"
                );
                IERC20(sideToken).safeTransfer(_recipient, _amount);
            }
        }
        emit FinishWithdraw(_token, _recipient, _amount, _depositId);
    }

    /// @notice Batch process withdrawal completion (improve throughput, use struct array to reduce stack pressure)
    function withdrawBatch(
        WithdrawalRequest[] calldata requests
    ) external whenNotPaused updateLastOperationTime {
        for (uint256 i = 0; i < requests.length; i++) {
            WithdrawalRequest calldata r = requests[i];
            _withdrawSingle(
                r.token,
                r.recipient,
                r.amount,
                r.depositId,
                r.sourceChainId,
                r.nonce,
                r.signatures,
                r.signerIndices
            );
        }
    }

    // ============ BLS Signature Verification Functions ============

    /// @notice Verify BLS signature
    /// @param messageHash Message hash
    /// @param signatures Signature array
    /// @return Verification result
    function verifySignatures(
        bytes32 messageHash,
        uint256[2] memory signatures,
        uint256[] memory signerIndices
    ) internal view returns (bool) {
        return _verifyBLSSignatures(messageHash, signatures, signerIndices);
    }

    /// @notice Internal BLS signature verification function
    /// @param messageHash Message hash
    /// @param signatures Signature array
    /// @return Verification result
    function _verifyBLSSignatures(
        bytes32 messageHash,
        uint256[2] memory signatures,
        uint256[] memory signerIndices
    ) internal view returns (bool) {
        require(blsPublicKeys.length > 0, "BLS public keys not set");
        require(blsThreshold > 0, "BLS threshold not set");
        require(signerIndices.length >= blsThreshold, "Insufficient signers");

        // Validate aggregated signature format (keep message minimal to reduce stack pressure)
        require(
            BLS.isValidSignature(signatures),
            "Invalid BLS signature format"
        );

        // Hash message to curve point
        (uint256[2] memory messagePoint, ) = BLS.hashToPoint(
            abi.encodePacked(messageHash)
        );

        // Build subset arrays by signer indices, with de-dup and bounds checks
        uint256 n = signerIndices.length;
        uint256[4][] memory pubkeys = new uint256[4][](n);
        uint256[2][] memory messages = new uint256[2][](n);
        bool[] memory seen = new bool[](blsPublicKeys.length);
        for (uint256 i = 0; i < n; i++) {
            uint256 idx = signerIndices[i];
            require(idx < blsPublicKeys.length, "Invalid signer index");
            require(!seen[idx], "Duplicate signer index");
            seen[idx] = true;
            pubkeys[i] = blsPublicKeys[idx];
            messages[i] = messagePoint;
        }

        // Verify aggregated signature against all public keys
        require(
            BLS.verifyMultiple(signatures, pubkeys, messages),
            "BLS signature verification failed"
        );

        return true;
    }

    // ============ Receive Functions ============

    /// @notice Receive native token
    receive() external payable {
        revert("Direct ETH transfers not allowed");
    }

    /// @notice Authorize upgrade
    /// @param newImplementation New implementation address
    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyMultiSig {}

    // ============ Emergency Functions ============

    /// @notice Pause contract
    function pause() external onlyMultiSig updateLastOperationTime {
        require(!paused(), "Contract is already paused");
        _pause();
    }

    /// @notice Unpause contract
    function unpause() external onlyMultiSig updateLastOperationTime {
        require(paused(), "Contract is not paused");
        _unpause();
    }

    /// @notice Rescue native token
    function rescueNative() external onlyMultiSig updateLastOperationTime {
        require(rescueRequestedAt != 0, "Rescue not requested");
        require(
            block.timestamp >= rescueRequestedAt + RESCUE_TIMELOCK,
            "Time lock period not elapsed"
        );
        uint256 balance = address(this).balance;
        require(balance > 0, "No native tokens to rescue");
        rescueRequestedAt = 0;
        (bool success, ) = address(multiSigWallet).call{value: balance}("");
        require(success, "Native token rescue failed");
        emit NativeTokenRescued(balance, address(multiSigWallet));
    }

    /// @notice Rescue ERC20 token
    /// @param token Token address
    /// @param amount Rescue amount
    function rescueERC20(
        address token,
        uint256 amount
    ) external onlyMultiSig updateLastOperationTime {
        require(rescueRequestedAt != 0, "Rescue not requested");
        require(
            block.timestamp >= rescueRequestedAt + RESCUE_TIMELOCK,
            "Time lock period not elapsed"
        );
        require(token != address(0), "Invalid token address");
        require(amount > 0, "Amount must be greater than 0");
        rescueRequestedAt = 0;
        IERC20(token).safeTransfer(address(multiSigWallet), amount);
        emit ERC20TokenRescued(token, amount, address(multiSigWallet));
    }

    /// @notice Submit rescue request, start rescue time lock countdown
    function requestRescue() external onlyMultiSig updateLastOperationTime {
        rescueRequestedAt = block.timestamp;
    }

    /// @notice Get remaining rescue time
    /// @return Remaining time (in seconds)
    function getRemainingRescueTime() external view returns (uint256) {
        if (rescueRequestedAt == 0) return type(uint256).max;
        if (block.timestamp >= rescueRequestedAt + RESCUE_TIMELOCK) return 0;
        return (rescueRequestedAt + RESCUE_TIMELOCK) - block.timestamp;
    }

    // ============ BLS Management Functions ============

    /// @notice Set BLS public keys
    /// @param _publicKeys Public key array
    /// @param _threshold Signature threshold
    function setBLSPublicKeys(
        uint256[4][] memory _publicKeys,
        uint256 _threshold
    ) external onlyMultiSig updateLastOperationTime {
        require(_publicKeys.length > 0, "No public keys provided");
        require(
            _threshold > 0 && _threshold <= _publicKeys.length,
            "Invalid threshold"
        );

        // Clear existence markers for old public keys
        for (uint256 i = 0; i < blsPublicKeys.length; i++) {
            bytes32 oldHash = _hashPublicKey(blsPublicKeys[i]);
            blsPublicKeyExists[oldHash] = false;
        }

        // Validate and write new public key set, use mapping for deduplication
        for (uint256 i = 0; i < _publicKeys.length; i++) {
            require(
                BLS.isValidPublicKey(_publicKeys[i]),
                "Invalid BLS public key"
            );
            bytes32 h = _hashPublicKey(_publicKeys[i]);
            require(!blsPublicKeyExists[h], "Duplicate BLS public key");
            blsPublicKeyExists[h] = true;
        }

        blsPublicKeys = _publicKeys;
        blsThreshold = _threshold;
    }

    /// @notice Get BLS public keys
    /// @return Public key array
    function getBLSPublicKeys() external view returns (uint256[4][] memory) {
        return blsPublicKeys;
    }

    /// @notice Get BLS signature threshold
    /// @return Signature threshold
    function getBLSThreshold() external view returns (uint256) {
        return blsThreshold;
    }

    // ============ Helper Functions ============

    /// @notice Convert uint256 to hexadecimal string
    /// @param value Value to convert
    /// @return Hexadecimal string
    function _toHexString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp >>= 4;
        }
        bytes memory buffer = new bytes(digits);
        for (uint256 i = digits; i > 0; i--) {
            buffer[i - 1] = _toHexChar(uint8(value & 0xf));
            value >>= 4;
        }
        return string(buffer);
    }

    /// @notice Convert uint8 to hexadecimal character
    /// @param value Value to convert
    /// @return Hexadecimal character
    function _toHexChar(uint8 value) internal pure returns (bytes1) {
        if (value < 10) {
            return bytes1(uint8(bytes1("0")) + value);
        } else {
            return bytes1(uint8(bytes1("a")) + value - 10);
        }
    }

    /// @notice Convert uint256 to string
    /// @param value Value to convert
    /// @return String
    function _toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    /// @notice Calculate hash of BLS public key
    function _hashPublicKey(
        uint256[4] memory pk
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(pk[0], pk[1], pk[2], pk[3]));
    }
}

